/**
 * @name Path traversal in file operations
 * @description Using user-controlled paths without validation can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-injection
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // CLI arguments
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = call
    )
    or
    // Environment variables
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("getenv").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Unsafe file write operations
 * @description Writing to file paths derived from user input without validation can lead to arbitrary file writes
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-file-write
 * @tags security
 *        external/cwe/cwe-059
 *        external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeFileWriteConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      // sys.argv
      call = API::moduleImport("sys").getMember("argv").getACall() and
      source = call
      or
      // Environment variables
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
      or
      // Command line args
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File open for write
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
      or
      // shutil operations
      call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "copytree", "move"]).getACall() and
      (sink = call.getArg(0) or sink = call.getArg(1))
      or
      // os.symlink
      call = API::moduleImport("os").getMember(["symlink", "link", "rename", "makedirs"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UnsafeFileWriteFlow = TaintTracking::Global<UnsafeFileWriteConfig>;
import UnsafeFileWriteFlow::PathGraph

from UnsafeFileWriteFlow::PathNode source, UnsafeFileWriteFlow::PathNode sink
where UnsafeFileWriteFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe file write from $@.", source.getNode(), "user input"
